package com.zpantry.recommendation.service;
import com.zpantry.ingredient.persistence.IngredientRepository; import com.zpantry.integration.ai.AiClient; import com.zpantry.pantry.persistence.PantryItemRepository; import com.zpantry.recipe.persistence.RecipeRepository; import com.zpantry.user.domain.FoodAllergen; import com.zpantry.user.persistence.UserProfileRepository; import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service;
@Service public class PersonalizedRecommendationService {
 private final UserProfileRepository profiles; private final PantryItemRepository pantry; private final IngredientRepository ingredients; private final RecipeRepository recipes; private final AiClient ai;
 public PersonalizedRecommendationService(UserProfileRepository p,PantryItemRepository q,IngredientRepository i,RecipeRepository r,AiClient a){profiles=p;pantry=q;ingredients=i;recipes=r;ai=a;}
 public Map<String,Object> recommend(UUID userId,int topK){var profile=profiles.findByUserIdAndDeletedFalse(userId).orElse(null); var blocked=profile==null||profile.getAllergies()==null?Set.<FoodAllergen>of():Arrays.stream(profile.getAllergies().split(",")).filter(s->!s.isBlank()).map(FoodAllergen::valueOf).collect(java.util.stream.Collectors.toSet()); var pantryItems=pantry.findAllByUserIdAndDeletedFalseOrderByExpiredAtAscCreatedAtAsc(userId); var available=pantryItems.stream().map(x->ingredients.findByIdAndDeletedFalse(x.ingredientId).orElse(null)).filter(Objects::nonNull).toList(); var candidates=recipes.findAllByDeletedFalse(PageRequest.of(0,100)).stream().filter(r->Collections.disjoint(allergens(r.allergens),blocked)).map(r->Map.of("recipeId",r.getId(),"recipeName",r.name,"ingredientNames",List.<String>of(),"instructionText",r.instructionText==null?"":r.instructionText)).toList(); var request=Map.of("userId",userId.toString(),"inputIngredientText",String.join(",",available.stream().map(i->i.name).toList()),"ingredients",available.stream().map(i->Map.of("ingredientId",i.getId(),"name",i.name,"quantity",0,"unit",i.unit==null?"":i.unit)).toList(),"candidateRecipes",candidates,"topK",Math.max(1,Math.min(topK,20))); return ai.post("/ai/recommend-meals",request); }
 private static Set<FoodAllergen> allergens(String value){return value==null||value.isBlank()?Set.of():Arrays.stream(value.split(",")).map(FoodAllergen::valueOf).collect(java.util.stream.Collectors.toSet());}
}
